import { resolveSiteUrl } from "./env";

/** Public site URL including any repository path, without a trailing slash. */
export const siteUrl = resolveSiteUrl(process.env);

/**
 * Absolute URL for a site path. Keeps the repository path on project sites
 * ("/projects/" → "https://user.github.io/repo/projects/").
 */
export const absoluteUrl = (path = "/") =>
  new URL(path.replace(/^\/+/, ""), `${siteUrl}/`).toString();

/** Social preview image, generated by src/app/og.png/route.tsx. */
export const ogImage = {
  url: absoluteUrl("og.png"),
  width: 1200,
  height: 630,
  alt: "Chanthorn Yoeun, Senior Software Engineer",
};
